INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-national-hockey-night-usa', 'GAMEBOYCOLOR', 'ESPN National Hockey Night (USA)', '2000', 'Sports', 'KCEO', '4', 'Ice Hockey', 'Ice hockey simulation with seasonal play and real-time tactics.', 'Win the Stanley Cup by outscoring opponents on the ice.', 'Intense pro-hockey sports action.', 'ESPN National Hockey Night brings hard-hitting action to GBC. Experience realistic gameplay and deep stats in this premier handheld hockey title.');